<!-- stage4-seo-specifications:start --><section class="product-seo-specifications"><h3>Thông số tra cứu</h3><table><tbody><tr><th scope="row">Tên sản phẩm</th><td>CẢM BIẾN LẠNH điều hòa ô tô cho Mazda CX-8 2019-2026 Denso KF0961J11</td></tr><tr><th scope="row">Mã sản phẩm</th><td>KF0961J11</td></tr><tr><th scope="row">Mã OEM</th><td>KF0961J11</td></tr><tr><th scope="row">Danh mục</th><td>Vật Tư &amp; Phụ Kiện Khác</td></tr><tr><th scope="row">Thương hiệu</th><td>DENSO</td></tr></tbody></table></section><!-- stage4-seo-specifications:end -->', 4, 0, 0, 0, 0, 'CẢM BIẾN LẠNH điều hòa ô tô cho Mazda CX-8 2019-2026 KF0961J11', 'CẢM BIẾN LẠNH điều hòa ô tô cho Mazda CX-8 2019-2026 Denso KF0961J11. Vật Tư & Phụ Kiện Khác tại CoolingSystem, hỗ trợ kiểm tra mã sản phẩm, tư vấn lắp đặt và.', 'cảm biến lạnh điều', '', 0, 0, NULL, 0, 1, 0);
